-- =====================================================================
-- Datos de prueba: un ejercicio para la lección "Fracciones equivalentes"
-- y una prueba para su tema. Ejecutar DESPUÉS de leccion_prueba.sql.
-- Formato de las preguntas: ver mathapp-web/docs/FORMATO_PREGUNTAS.md
-- =====================================================================
SET NAMES utf8mb4;

SET @leccion_id = (SELECT Leccion_Id FROM Lecciones
                   WHERE Leccion_Nombre = 'Fracciones equivalentes'
                   ORDER BY Leccion_Id DESC LIMIT 1);
SET @tema_id = (SELECT Tema_Id FROM Lecciones WHERE Leccion_Id = @leccion_id);
-- Si la lección no existe, los INSERT fallan con "cannot be null":
-- ejecuta primero leccion_prueba.sql.

INSERT INTO Ejercicios (Ejercicio_Contenido, Ejercicio_EsPrueba, Leccion_Id)
VALUES ('# Practica: fracciones equivalentes\n\nResponde las 4 preguntas. Cada vez que lo intentes, los números cambian.\n\n```pregunta\ntipo: fraccion\nvariables: a = 1..4, b = 5..9, k = 2..6\nenunciado: Amplifica $\\frac{[[a]]}{[[b]]}$ multiplicando el numerador y el denominador por [[k]]. ¿Qué fracción obtienes?\nnumerador: a*k\ndenominador: b*k\nforma: exacta\nexplicacion: $\\frac{[[a]] \\times [[k]]}{[[b]] \\times [[k]]} = \\frac{[[a*k]]}{[[b*k]]}$\n```\n\n```pregunta\ntipo: fraccion\nvariables: n = 1..4, d = 5..9, k = 2..5\nenunciado: Simplifica $\\frac{[[n*k]]}{[[d*k]]}$ hasta que sea **irreducible**.\nnumerador: n / mcd(n, d)\ndenominador: d / mcd(n, d)\nforma: irreducible\nexplicacion: Divide el numerador y el denominador entre [[k*mcd(n, d)]]: $\\frac{[[n*k]] \\div [[k*mcd(n, d)]]}{[[d*k]] \\div [[k*mcd(n, d)]]} = \\frac{[[n/mcd(n, d)]]}{[[d/mcd(n, d)]]}$\n```\n\n```pregunta\ntipo: opcion\nvariables: k = 2..5\nenunciado: ¿Cuál de estas fracciones es equivalente a $\\frac{2}{3}$?\nopciones:\n- [x] $\\frac{[[2*k]]}{[[3*k]]}$\n- [ ] $\\frac{[[2+k]]}{[[3+k]]}$\n- [ ] $\\frac{[[2*k]]}{3}$\n- [ ] $\\frac{3}{2}$\nexplicacion: Multiplicando arriba y abajo por [[k]]: $\\frac{2 \\times [[k]]}{3 \\times [[k]]} = \\frac{[[2*k]]}{[[3*k]]}$. Sumar el mismo número arriba y abajo **no** da una fracción equivalente.\n```\n\n```pregunta\ntipo: opcion\nvariables: k = 2..5\nenunciado: ¿Son equivalentes $\\frac{3}{5}$ y $\\frac{[[3*k]]}{[[5*k+1]]}$?\nopciones:\n- [ ] Sí\n- [x] No\nmezclar: no\nexplicacion: Con productos cruzados: $3 \\times [[5*k+1]] = [[3*(5*k+1)]]$ y $5 \\times [[3*k]] = [[15*k]]$. Los resultados son diferentes, entonces **no** son equivalentes.\n```\n', FALSE, @leccion_id);
SET @ejercicio_id = LAST_INSERT_ID();

INSERT INTO Pruebas (Prueba_Contenido, Prueba_EsPrueba, Tema_Id)
VALUES ('# Prueba: Fracciones equivalentes\n\nResponde las 7 preguntas y presiona **Entregar** al terminar. Si se acaba el tiempo, la prueba se entrega sola.\n\n```pregunta\ntipo: fraccion\nvariables: a = 1..3, b = 4..7, k = 2..4\nenunciado: Escribe una fracción equivalente a $\\frac{[[a]]}{[[b]]}$ cuyo denominador sea [[b*k]].\nnumerador: a*k\ndenominador: b*k\nforma: exacta\nexplicacion: Como $[[b]] \\times [[k]] = [[b*k]]$, multiplicamos también el numerador por [[k]]: $\\frac{[[a*k]]}{[[b*k]]}$\n```\n\n```pregunta\ntipo: fraccion\nvariables: n = 2|3|5, d = 7|9|11, k = 2..6\nenunciado: Simplifica $\\frac{[[n*k]]}{[[d*k]]}$ hasta que sea **irreducible**.\nnumerador: n / mcd(n, d)\ndenominador: d / mcd(n, d)\nforma: irreducible\nexplicacion: Dividimos arriba y abajo entre [[k*mcd(n, d)]] y obtenemos $\\frac{[[n/mcd(n, d)]]}{[[d/mcd(n, d)]]}$\n```\n\n```pregunta\ntipo: numero\nvariables: a = 1..5, b = 6..9, k = 2..5\nenunciado: Completa para que las fracciones sean equivalentes: $\\frac{[[a]]}{[[b]]} = \\frac{\\square}{[[b*k]]}$\nrespuesta: a*k\nexplicacion: El denominador se multiplicó por [[k]], así que el numerador también: $[[a]] \\times [[k]] = [[a*k]]$\n```\n\n```pregunta\ntipo: opcion\nenunciado: ¿Cuál de estas fracciones **no** es equivalente a $\\frac{1}{2}$?\nopciones:\n- [ ] $\\frac{3}{6}$\n- [ ] $\\frac{5}{10}$\n- [x] $\\frac{4}{6}$\n- [ ] $\\frac{7}{14}$\nexplicacion: $\\frac{4}{6}$ se simplifica a $\\frac{2}{3}$, no a $\\frac{1}{2}$. Las demás sí son la mitad.\n```\n\n```pregunta\ntipo: opcion\nenunciado: María comió $\\frac{2}{8}$ de un pastel y Pedro comió $\\frac{1}{4}$ de otro pastel del mismo tamaño. ¿Quién comió más?\nopciones:\n- [ ] María\n- [ ] Pedro\n- [x] Comieron lo mismo\nmezclar: no\nexplicacion: $\\frac{2}{8}$ se simplifica dividiendo entre 2: $\\frac{2 \\div 2}{8 \\div 2} = \\frac{1}{4}$. Comieron la misma cantidad.\n```\n\n```pregunta\ntipo: opcion\nenunciado: Para comprobar si $\\frac{4}{6}$ y $\\frac{10}{15}$ son equivalentes con productos cruzados, ¿qué resultados obtienes?\nopciones:\n- [x] $4 \\times 15 = 60$ y $6 \\times 10 = 60$\n- [ ] $4 \\times 10 = 40$ y $6 \\times 15 = 90$\n- [ ] $4 \\times 6 = 24$ y $10 \\times 15 = 150$\nexplicacion: Se multiplica en equis: el numerador de una por el denominador de la otra. Como los dos dan 60, **sí** son equivalentes.\n```\n\n```pregunta\ntipo: numero\nvariables: k = 2..9\nenunciado: ¿Por qué número se multiplicaron el numerador y el denominador de $\\frac{3}{4}$ para obtener $\\frac{[[3*k]]}{[[4*k]]}$?\nrespuesta: k\nexplicacion: $3 \\times [[k]] = [[3*k]]$ y $4 \\times [[k]] = [[4*k]]$\n```\n', TRUE, @tema_id);

SELECT @leccion_id AS Leccion_Id, @ejercicio_id AS Ejercicio_Id, @tema_id AS Tema_Id, LAST_INSERT_ID() AS Prueba_Id;
